    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;
  const totals1 = invoiceTotals(issued1);
  const partialPaid = recordPayment(issued1, { amount: 2000, date: '2025-10-08' }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;
  const totals2 = invoiceTotals(issued2);
  const paid = recordPayment(issued2, { amount: totals2.total, date: '2025-10-08' }).value;

  const result = vatSummary([partialPaid, paid]);
